// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        address recipient = address(0xDead);
        vm.deal(address(c), 1 wei);
        uint256 balanceBefore = address(recipient).balance;
        c.withdrawAll(recipient);
        bool recipientGotPaid = (address(recipient).balance == balanceBefore + 1 wei);
        assertTrue(recipientGotPaid);
    }
}
